import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

// Creature World: a compact, living prototype with procedural bodies and autonomous wildlife.
const canvas = document.querySelector('#world');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x9db99b, 26, 86);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, .1, 150);
scene.add(new THREE.HemisphereLight(0xe4f0d7, 0x475c3c, 2.0));
const sun = new THREE.DirectionalLight(0xffedc4, 3.2); sun.position.set(-18, 30, 12); sun.castShadow = true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-38; sun.shadow.camera.right=38; sun.shadow.camera.top=38; sun.shadow.camera.bottom=-38; scene.add(sun);
const mat = (color, roughness=.82, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const materials = { ground:mat(0x879a68), grass:mat(0x91a96d), dirt:mat(0x9c895f), water:mat(0x569b91,.25,{transparent:true,opacity:.8}), leaf:mat(0x628c55), leaf2:mat(0x9baa60), bark:mat(0x675341), rock:mat(0x858b72), flower:mat(0xe9c575), glow:mat(0xa6e5bb,.35,{emissive:0x61bda4,emissiveIntensity:1.5}), cell:mat(0x93d8cc,.36,{transparent:true,opacity:.9}), eye:mat(0xeff0d4,.35), pupil:mat(0x25382e,.3) };
const terrainGeo = new THREE.PlaneGeometry(150,150,90,90); terrainGeo.rotateX(-Math.PI/2);
const pos = terrainGeo.attributes.position;
for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i);let h=Math.sin(x*.115)*.52+Math.cos(z*.13)*.38+Math.sin((x+z)*.09)*.44;const d=Math.sqrt((x+3)**2+(z+2)**2);h+=Math.max(0,1-d/17)*.18;pos.setY(i,h)}
terrainGeo.computeVertexNormals();
const terrain = new THREE.Mesh(terrainGeo, materials.ground); terrain.receiveShadow=true;scene.add(terrain);
const water = new THREE.Mesh(new THREE.CircleGeometry(12.5,72),materials.water);water.rotation.x=-Math.PI/2;water.position.set(-3,.16,-2);water.receiveShadow=true;scene.add(water);
const waterRim = new THREE.Mesh(new THREE.RingGeometry(12.2,12.65,72),mat(0xa8a873));waterRim.rotation.x=-Math.PI/2;waterRim.position.set(-3,.18,-2);scene.add(waterRim);
const world = new THREE.Group(); scene.add(world);
const geo = new THREE.SphereGeometry(1,16,12);
function blob(parent, material, scale, location, segments=geo){const o=new THREE.Mesh(segments,material);o.scale.set(...scale);o.position.set(...location);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function cylinder(parent,material,r1,r2,length,location,segments=8){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,length,segments),material);o.position.set(...location);o.castShadow=true;parent.add(o);return o}
function createPlant(x,z,kind='flower'){
 const g=new THREE.Group();g.position.set(x,0,z);world.add(g);
 const stemMat=materials.leaf; const height=.55+Math.random()*.55;
 cylinder(g,stemMat,.035,.065,height,[0,height/2,0],6);
 const count=kind==='bloom'?5:3;
 for(let j=0;j<count;j++){let a=j*Math.PI*2/count;const l=blob(g,materials.leaf2,[.24,.07,.11],[Math.cos(a)*.16,height*.48,Math.sin(a)*.16]);l.rotation.y=-a}
 if(kind==='bloom')for(let j=0;j<5;j++){const a=j*Math.PI*2/5;blob(g,materials.flower,[.105,.075,.15],[Math.cos(a)*.15,height,Math.sin(a)*.15])}
 blob(g,kind==='food'?materials.glow:materials.flower,[.12,.12,.12],[0,height+.04,0]);g.userData={type:'plant',food:kind==='food',available:true};return g;
}
