for(let i=0;i<58;i++){let a=Math.random()*Math.PI*2,d=15+Math.random()*48;let x=-3+Math.cos(a)*d,z=-2+Math.sin(a)*d;if(Math.abs(x)<19&&Math.abs(z)<18){if(i%3===0)createTree(x,z,.65+Math.random()*.65);else createPlant(x,z,i%8===0?'food':i%4===0?'bloom':'plant')} }
