 const tone=isPlayer?new THREE.Color(state.color):new THREE.Color(def.color);const skin=mat(tone,.76);const dark=mat(tone.clone().multiplyScalar(.72),.85);const belly=mat(tone.clone().lerp(new THREE.Color(0xf0d6a5),.44),.9);
