 const tail=new THREE.Group();tail.position.set(0,.8*size,-.65*size);body.add(tail);let tailLength=(isPlayer?state.tail:.55)*1.3;const tailMesh=blob(tail,skin,[.21*size,.18*size,tailLength],[0,-.04*size,-tailLength*.64]);tailMesh.rotation.x=-.1;
 if(def.kind==='predator'||(isPlayer&&state.traits.has('spines'))){for(let i=0;i<5;i++){const spike=blob(body,mat(0xe1c38a),[.11*size,.22*size,.12*size],[0,1.18*size-i*.095*size,-.52*size+i*.25*size],new THREE.ConeGeometry(1,1,6));spike.rotation.x=-.25}}
