 if(isPlayer&&state.traits.has('fangs')||def.kind==='predator'){for(const side of [-1,1]){const fang=blob(body,materials.eye,[.06*size,.16*size,.06*size],[side*.16*size,.61*size,1.14*size],new THREE.ConeGeometry(1,1,6));fang.rotation.x=Math.PI}}
 return {root,body,torso,head,tail,tailMesh,limbs,def,isPlayer,skin,baseSpeed:isPlayer?2.4:def.speed,age:Math.random()*8,hunger:Math.random()*35,thirst:Math.random()*30,fear:0,health:100,stamina:100,dir:new THREE.Vector3(Math.random()-.5,0,Math.random()-.5).normalize(),think:Math.random()*2,energy:Math.random(),mood:'foraging',target:null,alert:0,sex:Math.random()<.5?'♀':'♂',generation:1};
}
