function updateHud(){const pct=n=>Math.max(0,Math.round(n));document.querySelector('#hunger-val').textContent=`${pct(state.hunger)}%`;document.querySelector('#thirst-val').textContent=`${pct(state.thirst)}%`;document.querySelector('#health-val').textContent=`${pct(state.health)}%`;document.querySelector('#hunger-meter').style.width=`${100-state.hunger}%`;document.querySelector('#thirst-meter').style.width=`${100-state.thirst}%`;document.querySelector('#health-meter').style.width=`${state.health}%`;document.querySelector('#dna-count').textContent=Math.floor(state.dna);document.querySelector('#evo-pct').textContent=`${Math.min(100,Math.round(state.dna/1.5))}%`;document.querySelector('#evo-bar').style.width=`${Math.min(100,state.dna/1.5)}%`;document.querySelector('#stage-name').textContent=state.stage?'CREATURE STAGE':'CELL STAGE';document.querySelector('#stage-icon').textContent=state.stage?'✦':'◉';document.querySelector('.stage-step').innerHTML=state.stage?'02 <span>/ 02</span>':'01 <span>/ 02</span>';document.querySelector('#grazer-count').textContent=fauna.filter(a=>a.def.kind!=='predator').length;document.querySelector('#hunter-count').textContent=fauna.filter(a=>a.def.kind==='predator').length;document.querySelector('#clock-label').textContent=`DAY ${String(state.day).padStart(2,'0')} · ${String(Math.floor(state.clock)).padStart(2,'0')}:${String(Math.floor((state.clock%1)*60)).padStart(2,'0')}`;document.querySelector('#biome-label').textContent=state.years?`THE VERDANT REACH · YEAR ${state.years.toLocaleString()}`:'THE VERDANT REACH';document.querySelector('#hunger-note').textContent=state.hunger<40?'sated':state.hunger<70?'hungry':'starving';}
function nearestFood(){let best=null,dist=Infinity;for(const p of foodSources){if(!p.userData.available)continue;const d=player.root.position.distanceTo(p.position);if(d<dist){dist=d;best=p}}return{item:best,dist}}
function eat(){if(!state.stage){const {item,dist}=nearestFood();if(item&&dist<3.7){item.userData.available=false;item.visible=false;state.hunger=Math.max(0,state.hunger-26);state.dna+=18;state.foodEaten++;addSparkles(item.position,0x88e2c6);notify('Plankton absorbed · +18 DNA');if(state.dna>=80&&!state.progress){state.progress=1;document.querySelector('#objective-title').textContent='Ready to leave the shallows';document.querySelector('#objective-text').textContent='Open the editor and evolve into a land-dwelling creature.';document.querySelector('#objective-toast').classList.remove('dismissed');notify('Evolution unlocked — shape your creature!')}setTimeout(()=>{item.visible=true;item.userData.available=true},14000);return}}
 if(state.stage){let {item,dist}=nearestFood();let prey=fauna.filter(a=>a.def.kind!=='predator'&&a.health>0).sort((a,b)=>a.root.position.distanceTo(player.root.position)-b.root.position.distanceTo(player.root.position))[0];const preyDist=prey?prey.root.position.distanceTo(player.root.position):99;if(state.traits.has('fangs')&&prey&&preyDist<2.6){prey.health-=42;state.hunger=Math.max(0,state.hunger-27);state.dna+=10;prey.fear=1;notify(prey.health<=0?'Prey captured · +10 DNA':'A bite lands!');if(prey.health<=0){prey.root.visible=false;setTimeout(()=>{prey.health=100;prey.root.visible=true;prey.root.position.copy(randAround(player.root.position,35));},24000)}return}if(item&&dist<3.7){item.userData.available=false;item.visible=false;state.hunger=Math.max(0,state.hunger-32);state.dna+=12;addSparkles(item.position);notify('Foraged sunspore · +12 DNA');setTimeout(()=>{item.visible=true;item.userData.available=true},14000);return}if(prey&&preyDist<3.5){state.hunger=Math.max(0,state.hunger-24);state.health=Math.max(10,state.health-4);notify('Scavenged a meal');return}}
 notify('Move closer to a food source');}
function evolve(){if(state.stage){notify('Your body is already adapted to land');return}if(state.dna<80){notify('Gather more plankton to unlock evolution');return}state.dna-=80;state.stage=1;state.progress=0;player.body.visible=true;player.cellForm.visible=false;player.skin.color.set(state.color);player.root.position.y=.12;player.baseSpeed=2.2+state.legs*.9;player.torso.scale.x=1;player.torso.scale.y=1;player.torso.scale.z=1;player.tailMesh.scale.z=.8+state.tail*1.1;player.tailMesh.position.z=-.2;player.limbs.forEach(l=>{l.pivot.scale.y=.8+state.legs*.6});document.querySelector('#stage-icon').textContent='✦';document.querySelector('#stage-name').textContent='CREATURE STAGE';document.querySelector('#stage-step').innerHTML='02 <span>/ 02</span>';document.querySelector('#objective-title').textContent='A new world underfoot';document.querySelector('#objective-text').textContent='Explore, forage, and watch the wildlife. Your adaptations shape how you survive.';document.querySelector('#objective-toast').classList.remove('dismissed');document.querySelector('#editor-modal').classList.remove('open');notify('Metamorphosis complete · Creature Stage');}
function movePlayer(dt,t){let inputX=0,inputZ=0;if(keys.KeyA||keys.ArrowLeft)inputX-=1;if(keys.KeyD||keys.ArrowRight)inputX+=1;if(keys.KeyW||keys.ArrowUp)inputZ-=1;if(keys.KeyS||keys.ArrowDown)inputZ+=1;let len=Math.hypot(inputX,inputZ);if(len){inputX/=len;inputZ/=len}const speed=player.baseSpeed*(keys.Space&&state.stamina>4?1.8:1)*(state.stage?1:1.13);if(len&&state.stamina>0){player.root.position.x+=inputX*speed*dt;player.root.position.z+=inputZ*speed*dt;player.root.rotation.y=Math.atan2(inputX,inputZ);state.stamina=Math.max(0,state.stamina-dt*(keys.Space?17:5));}else state.stamina=Math.min(100,state.stamina+dt*9);let x=player.root.position.x,z=player.root.position.z;const ground=Math.sin(x*.115)*.52+Math.cos(z*.13)*.38+Math.sin((x+z)*.09)*.44;const isWater=Math.hypot(x+3,z+2)<12.5;player.root.position.y=ground+(isWater?.2:.04)+Math.sin(t*7)*.055;if(!state.stage){player.body.visible=false;player.cellForm.visible=true;player.cellForm.position.y=Math.sin(t*3)*.06;player.cilia.forEach((c,i)=>c.rotation.z=Math.sin(t*8+i)*.3)}else{player.body.visible=true;player.cellForm.visible=false;const gait=len?Math.sin(t*(keys.Space?15:9)):Math.sin(t*2)*.04;player.limbs.forEach(l=>{l.pivot.rotation.x=len?gait*(l.front?1:-1)*.52:0});player.tail.rotation.y=Math.sin(t*4)*.23;player.head.rotation.x=Math.sin(t*3)*.04;player.body.position.y=len?Math.abs(Math.sin(t*9))*.05:0;}
 player.root.position.x=THREE.MathUtils.clamp(player.root.position.x,-63,63);player.root.position.z=THREE.MathUtils.clamp(player.root.position.z,-63,63);const desired=new THREE.Vector3(player.root.position.x+9,player.root.position.y+13,player.root.position.z+17);camera.position.lerp(desired,1-Math.exp(-dt*2.7));camera.lookAt(player.root.position.x,player.root.position.y+.55,player.root.position.z);}

