 const content={
  world:['The Verdant Reach','A sheltered freshwater basin ringed by old-growth forest. Forage in the shallows before venturing into hunter territory.'],
  species:['Species observed',`<b>${fauna.length} creatures</b> share this region. Glimmer grazers and mossback foragers browse the plants; thornback hunters pursue the herds. Duskwings keep to open ground.`],
  evolution:['Evolution','Gather plankton in the shallows to collect DNA. At 80 DNA, open the editor and choose a body plan before evolving. Your genes carry into the Creature Stage.'],
  family:['Lineage',`<b>${state.stage?'Generation 02':'Generation 01'} · ${state.sex}</b><br>Ancestor: the first drifting cell<br>DNA gathered: ${state.foodEaten} meals<br>Adaptations: ${[...state.traits].join(', ')||'none'}`]
 }[name];
 panelContent.innerHTML=`<div class="eyebrow">FIELD GUIDE</div><h2>${content[0]}</h2><p>${content[1]}</p><div class="panel-detail"><span>LOCAL POPULATION</span><strong>${fauna.length} wildlife</strong><small>${state.stage?'Land-adapted':'Shallows'} · Day ${state.day}</small></div>`;
 panel.classList.add('open');backdrop.classList.add('open');
}
function updatePreview(){const preview=$('#preview-creature');preview.style.setProperty('--creature-color',state.color);preview.style.transform=`translate(-50%,-50%) scale(${.82+state.body*.32})`;$('.preview-body').style.transform=`scale(${.8+state.body*.5},${.85+state.body*.35})`;$('.preview-tail').style.width=`${50+state.tail*55}px`;$('.preview-leg').style.height=`${30+state.legs*35}px`;}
function syncEditor(){state.body=Number($('#body-size').value)/100;state.legs=Number($('#leg-size').value)/100;state.tail=Number($('#tail-size').value)/100;updatePreview();}
function applyAdaptations(){
 player.body.children.filter?.(()=>false);
 const old=player.body.getObjectByName('editor-adaptations');if(old)player.body.remove(old);
 const group=new THREE.Group();group.name='editor-adaptations';player.body.add(group);
 const size=1,skin=player.skin;
 if(state.traits.has('wings'))for(const side of [-1,1]){const wing=blob(group,skin,[.58,.12,.67],[side*.64,1.02,-.08]);wing.rotation.z=side*.28;}
 if(state.traits.has('fangs'))for(const side of [-1,1]){const fang=blob(group,materials.eye,[.075,.19,.075],[side*.16,.61,1.14],new THREE.ConeGeometry(1,1,6));fang.rotation.x=Math.PI;}
 if(state.traits.has('spines'))for(let i=0;i<5;i++){const spike=blob(group,mat(0xe1c38a),[.11,.22,.12],[0,1.18-i*.095,-.52+i*.25],new THREE.ConeGeometry(1,1,6));spike.rotation.x=-.25;}
}
