document.querySelectorAll('.trait').forEach(button=>button.addEventListener('click',()=>{const trait=button.dataset.trait;if(state.traits.has(trait))state.traits.delete(trait);else state.traits.add(trait);button.classList.toggle('selected',state.traits.has(trait));}));
document.querySelectorAll('.swatch').forEach(button=>button.addEventListener('click',()=>{state.color=button.dataset.color;document.querySelectorAll('.swatch').forEach(b=>b.classList.toggle('selected',b===button));updatePreview();}));
document.querySelectorAll('.editor-tabs button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.editor-tabs button').forEach(b=>b.classList.toggle('selected',b===button));const target=button.textContent.toLowerCase();document.querySelector('.feature-picker').style.opacity=target==='features'?'1':'.72';document.querySelector('.color-row').style.opacity=target==='color'?'1':'.72';}));
document.querySelectorAll('.rail-button[data-panel]').forEach(button=>button.addEventListener('click',()=>{const name=button.dataset.panel;if(name==='world'&&panel.classList.contains('open'))closePanel();else{document.querySelectorAll('.rail-button').forEach(b=>b.classList.toggle('active',b===button));openPanel(name)}}));
$('#panel-close').addEventListener('click',closePanel);backdrop.addEventListener('click',closePanel);
$('#dismiss-objective').addEventListener('click',()=>$('#objective-toast').classList.add('dismissed'));
