document.addEventListener('keyup',event=>{keys[event.code]=false});
const directionKeys={up:['KeyW','ArrowUp'],down:['KeyS','ArrowDown'],left:['KeyA','ArrowLeft'],right:['KeyD','ArrowRight']};
document.querySelectorAll('[data-dir]').forEach(button=>{const set=(active)=>directionKeys[button.dataset.dir].forEach(k=>keys[k]=active);button.addEventListener('pointerdown',e=>{e.preventDefault();set(true)});['pointerup','pointercancel','pointerleave'].forEach(type=>button.addEventListener(type,()=>set(false)));});
$('#mobile-feed').addEventListener('click',eat);$('#mobile-dash').addEventListener('pointerdown',()=>keys.Space=true);['pointerup','pointercancel','pointerleave'].forEach(type=>$('#mobile-dash').addEventListener(type,()=>keys.Space=false));
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2))});
updatePreview();updateHud();requestAnimationFrame(animate);

